import time
import requests

class SpeechToTextService:
    def __init__(self, api_key, endpoint):
        self.api_key = api_key
        self.endpoint = endpoint

    def start_transcription(self, audio_file_path):
        url = f"{self.endpoint}/transcriptions"
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }
        data = {
            "audio_file_path": audio_file_path
        }
        response = requests.post(url, headers=headers, json=data)
        response.raise_for_status()
        return response.json()["job_id"]

    def poll_transcription(self, job_id):
        url = f"{self.endpoint}/transcriptions/{job_id}"
        headers = {
            "Authorization": f"Bearer {self.api_key}"
        }
        while True:
            response = requests.get(url, headers=headers)
            response.raise_for_status()
            job_status = response.json()["status"]
            if job_status == "completed":
                return response.json()["transcript"]
            elif job_status == "failed":
                raise Exception("Transcription failed")
            time.sleep(5)

# Example usage
api_key = "YOUR_API_KEY"
endpoint = "https://api.example.com"
service = SpeechToTextService(api_key, endpoint)

job_id = service.start_transcription("path/to/audio.wav")
transcript = service.poll_transcription(job_id)
